def get_inconsistent_system():
    """Returns the 'Inconsistent System' example matrix and vector."""
    A = sp.csr_matrix([
        [1, 1, 0],
        [1, 0, 0],
        [0, 1, 0],
        [0, 1, 0]
    ])
    b = np.array([16, 10, 5, 5.1])
    return A, b

